# Databricks notebook source
# MAGIC %md
# MAGIC # 02 · Build the retrieval evaluation dataset
# MAGIC ~600 shopper queries across six query types that mirror how the retailer's customers actually search. Each query is generated by
# MAGIC `databricks-gpt-oss-120b` from a **seed product**, so ground truth is known:
# MAGIC
# MAGIC | type | example | what it stresses |
# MAGIC |---|---|---|
# MAGIC | `known_item` | "milwaukee m18 1/4 hex impact driver kit" | exact product recall |
# MAGIC | `descriptive` | "something to hang my cords and hoses on the garage wall" | semantic understanding |
# MAGIC | `brand_constrained` | "Craftsman cordless drill with 2 batteries" | brand must match |
# MAGIC | `attribute_constrained` | "60W equivalent soft white LED, dimmable, 4 pack" | structured attributes |
# MAGIC | `exclusion` | "brushless impact driver, anything but DeWalt" | negation |
# MAGIC | `identifier` | "do you carry SKU 00176279?" | exact codes (keyword) |
# MAGIC
# MAGIC Ground truth (`expected_skus`, `constraints`, `expected_facts`) is derived **deterministically from the catalog**, not by the LLM.
# MAGIC Results are stored as MLflow evaluation datasets (`retrieval_eval`, plus a 100-query `retrieval_eval_judge` subset for LLM judges).
# MAGIC Run with `split=holdout` to build `retrieval_eval_holdout`: ~300 queries generated from products never used as dev seeds,
# MAGIC used to report final numbers for anything tuned on the dev set.

# COMMAND ----------

# MAGIC %uv pip install -U /Volumes/retail_consumer_goods/product_search/raw/wheels/product_retrieval-0.1.0-py3-none-any.whl databricks-langchain databricks-ai-search databricks-sdk mlflow

# COMMAND ----------

# MAGIC %restart_python

# COMMAND ----------

# MAGIC %run ./00_config

# COMMAND ----------

import random

dbutils.widgets.dropdown("split", "dev", ["dev", "holdout"])
SPLIT: str = dbutils.widgets.get("split")
HOLDOUT: bool = SPLIT == "holdout"
PER_TYPE: int = 50 if HOLDOUT else 100  # holdout: ~300 queries on products never used as dev seeds
OVERSAMPLE: float = 1.3
JUDGE_PER_TYPE: int = 17
RNG = random.Random(4242 if HOLDOUT else 42)

# COMMAND ----------

# MAGIC %md
# MAGIC ## Choose seed products
# MAGIC Seeds are spread across merchandise classes (weighted by √size so long-tail classes are represented). Brand-sensitive
# MAGIC types only use classes with at least three brands, so the constraint actually discriminates.

# COMMAND ----------

cat = pd.DataFrame([p.model_dump() for p in product_catalog().values()])
cat = cat[cat.brand_name.notna() & cat.merchandise_class.notna() & (cat.description.str.len() > 200)]

brands_per_class = cat.groupby("merchandise_class").brand_name.nunique()
multi_brand_classes = set(brands_per_class[brands_per_class >= 3].index)
top_other_brand: dict[tuple[str, str], str] = {}
for cls, grp in cat[cat.merchandise_class.isin(multi_brand_classes)].groupby("merchandise_class"):
    counts = grp.brand_name.value_counts()
    for brand in counts.index:
        top_other_brand[(cls, brand)] = next(b for b in counts.index if b != brand)

used: set[str] = set(spark.table(EVAL_SOURCE_TABLE).toPandas().seed_sku) if HOLDOUT else set()  # disjoint seeds


def sample_seeds(pool: pd.DataFrame, n: int) -> list[CatalogProduct]:
    pool = pool[~pool.sku.isin(used)]
    weights = pool.merchandise_class.map(pool.merchandise_class.value_counts() ** -0.5)
    picked = pool.sample(n=n, weights=weights, random_state=RNG.randint(0, 10**6))
    used.update(picked.sku)
    return [product_catalog()[s] for s in picked.sku]


n_gen = int(PER_TYPE * OVERSAMPLE)
attr_pool = cat[cat.description.str.count(r"; [A-Z][^:;]{1,40}: ") >= 5]
brand_pool = cat[cat.merchandise_class.isin(multi_brand_classes)]
seeds: dict[str, list[CatalogProduct]] = {
    "known_item": sample_seeds(cat, n_gen),
    "descriptive": sample_seeds(cat, n_gen),
    "brand_constrained": sample_seeds(brand_pool, n_gen),
    "attribute_constrained": sample_seeds(attr_pool, n_gen),
    "exclusion": sample_seeds(brand_pool[brand_pool.description.str.count(r"; [A-Z][^:;]{1,40}: ") >= 3], n_gen),
    "identifier": sample_seeds(cat, n_gen),
}
print({t: len(s) for t, s in seeds.items()}, "classes covered:", len({p.merchandise_class for s in seeds.values() for p in s}))

# COMMAND ----------

# MAGIC %md
# MAGIC ## Generate queries with `databricks-gpt-oss-120b`

# COMMAND ----------


TYPE_INSTRUCTIONS: dict[str, str] = {
    "known_item": "The shopper knows exactly which product they want. Refer to it by brand and product type plus one or two "
    "distinguishing details from the title (size, model, count), casually and slightly abbreviated. Do not copy the title verbatim.",
    "descriptive": "The shopper does NOT know the product name or brand. Describe the need, use case or problem it solves and one "
    "or two key characteristics. Never mention the brand, the exact product name, SKU or UPC.",
    "brand_constrained": "The shopper insists on this brand. Mention the brand and the product type plus one attribute. "
    "Do not copy the title verbatim.",
    "attribute_constrained": "The shopper needs specific specs. Mention the product type and 2-3 concrete attribute values taken "
    "from the structured attributes (e.g. voltage, size, color, wattage, count, kit vs tool-only). Never mention the brand.",
    "exclusion": "The shopper wants this kind of product with 1-2 of its concrete attributes, but explicitly does NOT want the "
    "brand '{exclude_brand}' (say so naturally, e.g. 'not {exclude_brand}', 'anything but {exclude_brand}'). Never mention "
    "the product's own brand.",
    "identifier": "The shopper references the product only by its code: use the {code_kind} '{code}' exactly as written, in a "
    "short natural request (e.g. 'do you have item ...'). Do not mention the brand or product name.",
}

GEN_PROMPT: str = (
    "You write realistic search queries for a hardware retailer's website and store associates.\n{instructions}\n\n"
    "Product:\nTitle: {name}\nBrand: {brand}\nCategory: {category}\nDetails: {details}\n\nReply with only the query text, no quotes or explanation."
)

gen_llm = chat(LLM_ENDPOINT, temperature=0.7)


class EvalCase(BaseModel):
    query: str
    query_type: str
    seed_sku: str
    expected_skus: list[str]
    constraints: dict[str, str | None]
    expected_facts: list[str]


by_name = cat.groupby("product_name").sku.apply(list).to_dict()
by_desc = cat.groupby("description").sku.apply(list).to_dict()


def build_case(query_type: str, p: CatalogProduct) -> EvalCase | None:
    exclude_brand = top_other_brand.get((p.merchandise_class, p.brand_name)) if query_type == "exclusion" else None
    code_kind, code = ("SKU", p.sku) if RNG.random() < 0.6 else ("UPC", p.upc)
    instructions = TYPE_INSTRUCTIONS[query_type].format(exclude_brand=exclude_brand, code_kind=code_kind, code=code)
    prompt = GEN_PROMPT.format(
        instructions=instructions, name=p.product_name, brand=p.brand_name, category=p.merchandise_class, details=p.description[:1200]
    )
    query: str | None = None
    for _ in range(3):  # transient throttling or an empty reply: retry, then drop the seed (we oversample)
        try:
            query = message_text(gen_llm.invoke(prompt)).strip().strip('"').splitlines()[0] or None
            if query:
                break
        except Exception as e:
            failures[f"{type(e).__name__}: {str(e)[:120]}"] += 1
    if query is None:
        return None

    expected = [p.sku] if query_type == "identifier" else sorted(set(by_name.get(p.product_name, [])) | set(by_desc.get(p.description, [])) | {p.sku})
    constraints = {
        "brand_name": p.brand_name if query_type == "brand_constrained" else None,
        "merchandise_class": p.merchandise_class if query_type in ("attribute_constrained", "exclusion") else None,
        "exclude_brand": exclude_brand,
    }
    facts = [f"Recommends the {p.product_name} (SKU {p.sku})"]
    if exclude_brand:
        facts.append(f"Does not recommend any {exclude_brand} product")
    return EvalCase(query=query, query_type=query_type, seed_sku=p.sku, expected_skus=expected, constraints=constraints, expected_facts=facts)


from collections import Counter

failures: Counter = Counter()
mlflow.langchain.autolog(disable=True)
jobs = [(t, p) for t, ps in seeds.items() for p in ps]
with ThreadPoolExecutor(max_workers=8) as pool:
    cases = [c for c in pool.map(lambda tp: build_case(*tp), jobs) if c]
mlflow.langchain.autolog()
print(f"generated {len(cases)} / {len(jobs)}", failures.most_common(5))

# COMMAND ----------

# MAGIC %md
# MAGIC ## Validate & balance
# MAGIC Reject queries that leak the answer (brand/SKU where it shouldn't appear) or miss the required element, then keep 100 per type.

# COMMAND ----------


def norm(s: str | None) -> str:
    return re.sub(r"[^a-z0-9]", "", (s or "").lower().replace("+", "and").replace("&", "and"))


def is_valid(c: EvalCase) -> bool:
    p, q = product_catalog()[c.seed_sku], norm(c.query)
    mentions_brand = norm(p.brand_name) in q
    mentions_code = p.sku in c.query or p.upc in c.query
    if not 8 <= len(c.query) <= 200:
        return False
    match c.query_type:
        case "identifier":
            return mentions_code and not mentions_brand
        case "brand_constrained" | "known_item":
            return mentions_brand and not mentions_code
        case "exclusion":
            return norm(c.constraints["exclude_brand"]) in q and not mentions_brand and not mentions_code
        case _:
            return not mentions_brand and not mentions_code


valid = [c for c in cases if is_valid(c)]
rejected = Counter(c.query_type for c in cases if not is_valid(c))
seen: set[str] = set()
balanced: list[EvalCase] = []
for qtype in QUERY_TYPES:
    for c in [c for c in valid if c.query_type == qtype]:
        if c.query.lower() not in seen and sum(b.query_type == qtype for b in balanced) < PER_TYPE:
            seen.add(c.query.lower())
            balanced.append(c)

eval_df = pd.DataFrame([c.model_dump() for c in balanced])
eval_df["constraints"] = eval_df.constraints.map(json.dumps)
print(f"valid {len(valid)} / {len(cases)}; kept {len(eval_df)}; rejected by type: {dict(rejected)}")
display(eval_df.groupby("query_type").size().rename("queries").reset_index())

# COMMAND ----------

display(eval_df.groupby("query_type").head(3)[["query_type", "query", "expected_skus", "constraints"]])

# COMMAND ----------

# MAGIC %md
# MAGIC ## Persist: Delta source table + MLflow evaluation datasets

# COMMAND ----------

spark.createDataFrame(eval_df).write.mode("overwrite").option("overwriteSchema", "true").saveAsTable(
    HOLDOUT_SOURCE_TABLE if HOLDOUT else EVAL_SOURCE_TABLE
)

judge_df = eval_df.groupby("query_type").sample(n=JUDGE_PER_TYPE, random_state=7)


def to_records(df: pd.DataFrame) -> list[dict[str, Any]]:
    return [
        {
            "inputs": {"query": r.query},
            "expectations": {
                "expected_skus": list(r.expected_skus),
                "constraints": json.loads(r.constraints),
                "expected_facts": list(r.expected_facts),
                "query_type": r.query_type,
            },
        }
        for r in df.itertuples()
    ]


for name, df in [(HOLDOUT_DATASET, eval_df)] if HOLDOUT else [(EVAL_DATASET, eval_df), (JUDGE_DATASET, judge_df)]:
    spark.sql(f"DROP TABLE IF EXISTS {name}")
    ds = mlflow.genai.datasets.create_dataset(name=name, experiment_id=experiment.experiment_id)
    ds.merge_records(to_records(df))
    print(f"{name}: {len(ds.to_df())} records")

# COMMAND ----------

dbutils.notebook.exit(json.dumps({"generated": len(cases), "failures": failures.most_common(5), "rejected": rejected, "kept": eval_df.query_type.value_counts().to_dict()}))
